package main

import (
    "encoding/xml"
    "io"
    "strings"
)

// node retains the lexical data needed by the generator, in document order.
type node struct {
    XMLName xml.Name
    Attr []xml.Attr
    Children []*node
    Text string
}

func (n *node) UnmarshalXML(d *xml.Decoder, start xml.StartElement) error {
    n.XMLName = start.Name
    n.Attr = start.Attr
    var text strings.Builder
    for {
        tok, err := d.Token()
        if err != nil { return err }
        switch t := tok.(type) {
        case xml.StartElement:
            child := new(node)
            if err := d.DecodeElement(child, &t); err != nil { return err }
            n.Children = append(n.Children, child)
        case xml.CharData:
            text.Write(t)
        case xml.EndElement:
            n.Text = text.String()
            return nil
        }
    }
}

func parseXML(data []byte) (*node, error) {
    d := xml.NewDecoder(strings.NewReader(string(data)))
    n := new(node)
    if err := d.Decode(n); err != nil { return nil, err }
    return n, nil
}

func (n *node) get(key string) string {
    if n == nil { return "" }
    for _, a := range n.Attr { if a.Name.Local == key { return a.Value } }
    return ""
}
func (n *node) all(key string) []*node {
    if n == nil { return nil }
    var out []*node
    for _, c := range n.Children { if c.XMLName.Local == key { out = append(out,c) } }
    return out
}
func (n *node) one(key string) *node {
    if n == nil { return nil }
    for _, c := range n.Children { if c.XMLName.Local == key { return c } }
    return nil
}
func (n *node) walk(f func(*node)) {
    if n == nil { return }; f(n)
    for _, c := range n.Children { c.walk(f) }
}
func local(s string) string {
    if p := strings.IndexByte(s, ':'); p >= 0 { return s[p+1:] }
    return s
}

var _ io.Reader
EOF
