package main

import (
    "fmt"
    "strings"
    "unicode"
    "unicode/utf8"
)

const wsdlNS = "http://schemas.xmlsoap.org/wsdl/"
const xsdNS = "http://www.w3.org/2001/XMLSchema"
const soapNS = "http://schemas.xmlsoap.org/wsdl/soap/"

func (n *node) allNS(key, ns string) []*node {
    var out []*node
    if n != nil { for _, c := range n.Children { if c.XMLName.Local == key && c.XMLName.Space == ns { out = append(out,c) } } }
    return out
}
func (n *node) oneNS(key, ns string) *node {
    if n != nil { for _, c := range n.Children { if c.XMLName.Local == key && c.XMLName.Space == ns { return c } } }
    return nil
}
func (n *node) xs(key string) []*node { return n.allNS(key,xsdNS) }
func (n *node) x(key string) *node { return n.oneNS(key,xsdNS) }
func (n *node) ws(key string) []*node { return n.allNS(key,wsdlNS) }
func (n *node) w(key string) *node { return n.oneNS(key,wsdlNS) }

var keywords = func() map[string]bool {
    m:=map[string]bool{}
    for _, k := range strings.Fields("break default func interface select case defer go map struct chan else goto package switch const fallthrough if range type continue for import return var") { m[k]=true }
    return m
}()
var goScalars = func() map[string]bool {
    m:=map[string]bool{}
    for _, k := range strings.Fields("int int8 int16 int32 int64 uint16 uint32 byte bool float32 float64 string") { m[k]=true }
    return m
}()

func clean(s string) string {
    var out strings.Builder
    for _, r := range s {
        switch r {
        case '-', '.': out.WriteByte('_')
        case '+': out.WriteString("Plus")
        case '@': out.WriteString("At")
        default:
            if (r >= 'a' && r <= 'z') || (r >= 'A' && r <= 'Z') || (r >= '0' && r <= '9') || r == '_' { out.WriteRune(r) }
        }
    }
    s=out.String()
    if keywords[s] { s += "_" }
    return s
}
func upper(s string) string {
    if s == "" { return "EmptyString" }
    if goScalars[s] { return s }
    r,n := utf8.DecodeRuneInString(s)
    return string(unicode.ToUpper(r))+s[n:]
}
func lower(s string) string {
    if s == "" { return "" }
    r,n := utf8.DecodeRuneInString(s)
    return string(unicode.ToLower(r))+s[n:]
}
func fieldName(s string) string {
    s = clean(s)
    if s == "string" { s = "astring" }
    return upper(s)
}

var primitives = map[string]string{
    "string":"string", "token":"string", "boolean":"bool", "decimal":"float64",
    "float":"float32", "double":"float64", "dateTime":"soap.XSDDateTime",
    "date":"soap.XSDDate", "time":"soap.XSDTime", "hexBinary":"[]byte", "base64Binary":"[]byte",
    "anyURI":"AnyURI", "NCName":"NCName", "integer":"int32", "long":"int64", "int":"int32",
    "short":"int16", "byte":"int8", "nonNegativeInteger":"uint32", "unsignedLong":"uint64",
    "unsignedInt":"uint32", "unsignedShort":"uint16", "unsignedByte":"byte", "anyType":"AnyType",
}
func typeName(t string, pointer bool) string {
    t=local(t)
    if t == "" { return "string" }
    if result, ok := primitives[t]; ok { return result }
    s:=upper(clean(t))
    if pointer { s="*"+s }
    return s
}
func elementType(t string, nillable bool, many bool) string {
    s:=typeName(t,true)
    if nillable && !strings.HasPrefix(s,"*") { s="*"+s }
    if many { s="[]"+s }
    return s
}

type generator struct {
    root *node
    schemas []*schema
    pkg string
    public bool
    uses map[string]map[string]bool
}
func newGenerator(root *node, schemas []*schema, pkg string, public bool) *generator {
    g:=&generator{root:root, schemas:schemas, pkg:pkg, public:public, uses:map[string]map[string]bool{}}
    for _, s := range schemas {
        s.n.walk(func(n *node) {
            if n.XMLName.Local != "element" || n.XMLName.Space != xsdNS || n.get("type")=="" { return }
            t:=local(n.get("type"))
            if g.uses[t]==nil { g.uses[t]=map[string]bool{} }
            g.uses[t][n.get("name")]=true
        })
    }
    return g
}
func (g *generator) decl(name string) string {
    name = clean(name)
    if name == "string" { name="astring" }
    if g.public { return upper(name) }
    return name
}
func (g *generator) enumName(name string) string {
    name = clean(name)
    if g.public { return upper(name) }
    return name
}
func docs(n *node) string {
    d := n.x("annotation").x("documentation")
    if d == nil { return "" }
    return d.Text
}
func comment(s string) string {
    if s == "" { return "" }
    lines:=strings.Split(s,"\n")
    for i,line:=range lines { lines[i]="// "+strings.TrimSpace(line) }
    return strings.Join(lines,"\n")+"\n"
}
func indent(s string) string {
    if s=="" { return s }
    return "\t"+strings.ReplaceAll(strings.TrimSuffix(s,"\n"),"\n","\n\t")+"\n"
}

func (g *generator) simple(n *node, name string) string {
    var b strings.Builder
    if d:=docs(n); d!="" { b.WriteString(comment(d)); b.WriteByte('\n') }
    base:="interface{}"
    r:=n.x("restriction")
    if r!=nil { base=typeName(r.get("base"),false) }
