func TestIdentifiers(t *testing.T) {
    for raw,want:=range map[string]string{
        "foo-bar":"Foo_bar", "a.b":"A_b", "a+b@c":"APlusbAtc",
        "type":"Type_", "string":"Astring", "int":"int", "éclair":"Éclair",
    } {
        if got:=fieldName(raw);got!=want { t.Errorf("%q: %s != %s",raw,got,want) }
    }
    if got:=elementType("s:int",true,true);got!="[]*int32" { t.Fatal(got) }
    if got:=elementType("s:base64Binary",false,true);got!="[][]byte" { t.Fatal(got) }
    if got:=elementType("t:Record",true,true);got!="[]*Record" { t.Fatal(got) }
}

func TestUnformattedFailure(t *testing.T) {
    data,err:=os.ReadFile("assets/stock.wsdl")
    if err!=nil { t.Fatal(err) }
    g:=fixtureGenerator(t,data,"bad-package",true)
    raw:=g.rawClient()
    path:=filepath.Join(t.TempDir(),"invalid.go")
    err=save(path,raw)
    if err==nil || err.Error()!="4:12: expected ';', found '-'" { t.Fatalf("unexpected error: %v",err) }
    written,err:=os.ReadFile(path)
    if err!=nil || string(written)!=raw { t.Fatal("unformatted output not preserved") }
}

func TestSchemaDependencies(t *testing.T) {
    dir:=t.TempDir()
    schemaText:=func(body string) string { return `<schema xmlns="http://www.w3.org/2001/XMLSchema">`+body+`</schema>` }
    for name,data:=range map[string]string{
        "a.xsd":schemaText(`<include schemaLocation="b.xsd"/><element name="A" type="string"/>`),
        "b.xsd":schemaText(`<include schemaLocation="a.xsd"/><element name="B" type="int"/>`),
    } { if err:=os.WriteFile(filepath.Join(dir,name),[]byte(data),0600);err!=nil { t.Fatal(err) } }
    n,err:=parseXML([]byte(schemaText(`<include schemaLocation="a.xsd"/>`)))
    if err!=nil { t.Fatal(err) }
    start:=&schema{n:n}
    all:=[]*schema{start}
    l:=&loader{client:http.DefaultClient,seen:make(map[string]bool)}
    if err:=l.resolve(start,filepath.Join(dir,"root.wsdl"),&all);err!=nil { t.Fatal(err) }
    if len(all)!=3 { t.Fatalf("expected three schemas, got %d",len(all)) }
    if all[1].n.x("element").get("name")!="B" || all[2].n.x("element").get("name")!="A" { t.Fatal("incorrect dependency ordering") }
}

func TestHTTPStatusAndXML(t *testing.T) {
    srv:=httptest.NewServer(http.HandlerFunc(func(w http.ResponseWriter,r *http.Request){
        if r.URL.Path=="/ok" { fmt.Fprint(w,"<definitions/>");return }
        w.WriteHeader(404)
    }))
    defer srv.Close()
    l:=&loader{client:srv.Client(),seen:make(map[string]bool)}
    data,_,err:=l.read(srv.URL+"/ok")
    if err!=nil || string(data)!="<definitions/>" { t.Fatalf("read: %q %v",data,err) }
    _,_,err=l.read(srv.URL+"/missing")
    if err==nil || err.Error()!="Received response code 404" { t.Fatal(err) }
    _,err=parseXML([]byte("<definitions>\n<types></definitions>"))
    if err==nil || !strings.Contains(err.Error(),"element <types> closed by </definitions>") { t.Fatal(err) }
}
